import { edit_delete_payslips } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    payslipedition: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      employeelist: "",
      loading: false,
      reasonchange: "",
      depertmentlist: "",
      depertmentitems: []
    };
  },
  watch: {
    payslipedition: {
      async handler() {
        if (this.payslipedition == true) {}
      },
      immediate: true
    }
  },
  computed: {
    filteredEmployeeData() {
      var {
        organization_id,
        employee_name,
        month_year,
        month,
        email_id,
        year,
        payslip_id,
        payslip_created_on,
        ...rest
      } = this.rowInfo;
      return rest;
    }
  },
  methods: {
    formatLabel(key) {
      return key.replace(/_/g, " ").replace(/\b\w/g, char => char.toUpperCase());
    },
    close_dialog() {
      this.$refs.form.resetValidation();
      this.$emit("clicked", 0);
    },
    async saveData() {
      if (this.$refs.form.validate()) {
        var updatedvalue = {
          ...this.rowInfo,
          ...this.filteredEmployeeData
        };
        this.rowInfo;
        delete updatedvalue.payslip_id;
        this.loading = true;
        try {
          let result = await API.graphql(graphqlOperation(edit_delete_payslips, {
            input: {
              Update_params: JSON.stringify([updatedvalue]),
              payslip_id: this.rowInfo.payslip_id,
              action_type: "UPDATE_PAYSLIP"
            }
          }));
          var response = JSON.parse(result.data.edit_delete_payslips);
          this.loading = false;
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
            this.$emit("usertimesheet", "dataValue");
          } else {
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          this.$emit("errorMsg", error.errors[0].message);
          this.loading = false;
        }
      }
    }
  }
};
